  SELECT 1 FROM pet_friendly_places WHERE
    latitude  BETWEEN 44.165361 AND 44.183361
    AND longitude BETWEEN 7.072381 AND 7.096381
    AND LOWER(TRIM(name)) = LOWER(TRIM('Parc national du Mercantour CT (coeur terrestre)'))
);

